 const initial=new Set(),ids=new Set();for(const c of s.cashflows){if(!c.id||ids.has(c.id)||!['real','paper'].includes(c.book)||!s.accounts.includes(c.account)||!['initial','deposit','withdraw','dividend','interest'].includes(c.kind)||!E.date(c.date)||!Number.isFinite(c.amount)||c.amount<=0)throw Error('資金異動格式或編號異常');ids.add(c.id);if(c.kind==='initial'){const k=c.book+'|'+c.account;if(initial.has(k))throw Error('相同帳戶不能有兩筆初始資金');initial.add(k);}}
 const goalIds=new Set();for(const g of s.goals){if(!g.id||goalIds.has(g.id)||typeof g.title!=='string'||!g.title.trim()||g.title.length>60||!['profit','trade','discipline'].includes(g.kind)||!['real','paper'].includes(g.book)||!s.accounts.includes(g.account)||!E.date(g.start)||!E.date(g.end)||g.start>g.end||!Number.isFinite(g.target)||g.target<=0||!Object.hasOwn(window.AcademyGoalArt.themes,g.theme)||!['male','female','neutral'].includes(g.gender)||!['full','lite','static'].includes(g.motion)||(g.sceneStyle!==undefined&&!['calm','playful','cinematic'].includes(g.sceneStyle))||(g.renderer!==undefined&&!['illustrated','leek3d'].includes(g.renderer)))throw Error('目標備份格式異常，尚未寫入');goalIds.add(g.id);}
