 const f=d.querySelector('form');function preview(){const host=d.querySelector('[data-goal-preview]');A.dispose(host);host.innerHTML=A.scene(field(f,'theme'),+field(f,'preview'),field(f,'gender'),field(f,'motion'),'',{sceneStyle:field(f,'sceneStyle'),renderer:field(f,'renderer')});A.mount(host);f.elements.renderer.closest('label').hidden=field(f,'theme')!=='immortal';d.querySelector('[data-goal-cycle]').hidden=field(f,'kind')!=='trade';d.querySelector('[data-goal-adherence]').hidden=field(f,'kind')!=='discipline';}f.onchange=e=>{if(!e.target.closest('.mt-evolution'))preview();};preview();
